// INV 01 · INV 02 — Plano_de_Testes_QA_MatchWallet.md §10 (docs-test/areas/inv.md).
// INV 02 valida só a apresentação dos números que a API devolve (formatação, vínculo, links).
// A reconciliação com a massa administrativa (cálculo real) depende de dados conhecidos no banco
// e fica fora desta suíte.

const CLIENTE_SEM_AVALIACAO = {
  id: '11111111-1111-4111-8111-111111111111',
  nome: 'Maria Teste',
  email: 'maria@teste.com',
  perfil: 'cliente',
  perfilInvestidor: null,
  carteiraVinculada: null,
}

const VINCULADA = { id: 'cart-mod', nome: 'Carteira Moderada', perfilAlvo: 'MODERADO' }

const CLIENTE_VINCULADO = {
  ...CLIENTE_SEM_AVALIACAO,
  perfilInvestidor: 'MODERADO',
  carteiraVinculada: VINCULADA,
}

const CARTEIRA = {
  ...VINCULADA,
  descricao: 'Equilíbrio entre renda fixa e ações',
  ativa: true,
  criadoEm: '2026-01-01T00:00:00.000Z',
  versaoAtual: {
    id: 'v1',
    mesReferencia: '2026-10',
    publicada: true,
    publicadaEm: '2026-10-01T00:00:00.000Z',
    itens: [
      {
        id: 'i1',
        ativoId: 'a1',
        tickerCodigo: 'ITUB4',
        nomeAtivo: 'Itaú Unibanco',
        classeAtivo: 'Ações',
        pesoPercentual: 60,
        statusMovimentacao: 'MANTER',
      },
      {
        id: 'i2',
        ativoId: 'a2',
        tickerCodigo: 'TESO',
        nomeAtivo: 'Tesouro Selic',
        classeAtivo: 'Renda fixa',
        pesoPercentual: 40,
        statusMovimentacao: 'MANTER',
      },
    ],
  },
}

const SEM_RELATORIOS = { items: [], total: 0, page: 1, pageSize: 1 }

describe('Plano QA · Área do investidor (painel)', () => {
  beforeEach(() => {
    cy.bloquearApi()
  })

  it('INV 01 · cliente sem avaliação abre painel, minha carteira e conta → instrução para avaliar, indicadores "sem dado" e nenhuma carteira fictícia', () => {
    cy.intercept('GET', '**/api/v1/auth/me', CLIENTE_SEM_AVALIACAO).as('me')
    cy.stubApi(
      'GET',
      '/dashboard/investidor',
      {
        usuario: { nome: 'Maria Teste', perfilInvestidor: null },
        suitabilityRealizado: false,
        suitabilityVencido: false,
        carteira: null,
        ultimoRelatorio: null,
        movimentacoesMes: { novasEntradas: 0, saidas: 0 },
      },
      'dashboard',
    )
    cy.stubApi('GET', '/relatorios/meus-relatorios*', SEM_RELATORIOS, 'relatorios')
    // Sem avaliação o painel nem deve pedir desempenho: se pedir, 422 como o servidor responde.
    cy.stubErroApi(
      'GET',
      '/minha-carteira/performance',
      { status: 422, code: 'SUITABILITY_PENDENTE', message: 'Avaliação pendente.' },
      'performance',
    )

    // Painel.
    cy.visit('/')
    cy.wait('@dashboard')
    cy.contains('h1', 'Complete sua avaliação de perfil').should('be.visible')
    cy.contains('Você ainda não tem uma carteira recomendada vinculada').should('be.visible')
    cy.contains('[data-slot="kpi-card"]', 'Rentabilidade do mês')
      .should('contain.text', 'Sem dado ainda')
      .invoke('text')
      .should('not.match', /\d/)
    cy.contains('[data-slot="kpi-card"]', 'Acumulado no ano')
      .should('contain.text', 'Sem dado ainda')
      .invoke('text')
      .should('not.match', /\d/)
    cy.contains('[data-slot="kpi-card"]', '% do CDI no ano').should('contain.text', '—')
    cy.contains('[data-slot="kpi-card"]', 'Ativos na carteira')
      .should('contain.text', '—')
      .and('contain.text', 'Sem carteira vinculada')
    cy.get('@performance.all').should('have.length', 0)

    // Minha carteira: CTA leva à avaliação.
    cy.visit('/carteira')
    cy.contains('h1', 'Você ainda não tem uma carteira vinculada').should('be.visible')
    cy.contains('a', 'Fazer avaliação de perfil').click()
    cy.location('pathname').should('eq', '/avaliacao-perfil')

    // Conta: sem perfil, sem carteira e CTA para a avaliação.
    cy.visit('/conta')
    cy.contains('dd', 'Nenhuma ainda').should('be.visible')
    cy.contains('Você ainda não fez a avaliação de perfil.').should('be.visible')
    cy.contains('a', 'Fazer avaliação').click()
    cy.location('pathname').should('eq', '/avaliacao-perfil')
  })

  // O plano (INV 01) pede que os CTAs do painel levem à avaliação de perfil.
  it('INV 01 · painel de cliente sem avaliação → a instrução oferece link para a avaliação de perfil', () => {
    cy.intercept('GET', '**/api/v1/auth/me', CLIENTE_SEM_AVALIACAO).as('me')
    cy.stubApi(
      'GET',
      '/dashboard/investidor',
      {
        usuario: { nome: 'Maria Teste', perfilInvestidor: null },
        suitabilityRealizado: false,
        suitabilityVencido: false,
        carteira: null,
        ultimoRelatorio: null,
        movimentacoesMes: { novasEntradas: 0, saidas: 0 },
      },
      'dashboard',
    )
    cy.stubApi('GET', '/relatorios/meus-relatorios*', SEM_RELATORIOS, 'relatorios')

    cy.visit('/')
    cy.wait('@dashboard')
    cy.get('a[href="/avaliacao-perfil"]').should('exist').and('be.visible').click()
    cy.location('pathname').should('eq', '/avaliacao-perfil')
  })

  it('INV 02 · cliente com carteira e retornos em M → indicadores do vínculo e links para os detalhes', () => {
    cy.intercept('GET', '**/api/v1/auth/me', CLIENTE_VINCULADO).as('me')
    cy.stubApi(
      'GET',
      '/dashboard/investidor',
      {
        usuario: { nome: 'Maria Teste', perfilInvestidor: 'MODERADO' },
        suitabilityRealizado: true,
        suitabilityVencido: false,
        carteira: {
          id: CARTEIRA.id,
          nome: CARTEIRA.nome,
          totalAtivos: 2,
          rentabilidadeUltimoMes: 1.5,
        },
        ultimoRelatorio: null,
        movimentacoesMes: { novasEntradas: 0, saidas: 0 },
      },
      'dashboard',
    )
    cy.stubApi(
      'GET',
      '/minha-carteira/performance',
      {
        carteiraNome: CARTEIRA.nome,
        mesAtual: { competencia: '2026-10', rentabilidade: 1.5, cdi: 1, percentualCdi: 150 },
        acumuladoAno: { rentabilidade: 12.3, cdi: 10 },
        historicoUltimosMeses: [],
      },
      'performance',
    )
    cy.stubApi('GET', `/carteiras/${CARTEIRA.id}`, CARTEIRA, 'detalhe')
    cy.stubApi(
      'GET',
      `/carteiras/${CARTEIRA.id}/movimentacoes*`,
      {
        carteiraId: CARTEIRA.id,
        mesReferencia: '2026-10',
        movimentacoes: {
          entradas: [],
          saidas: [],
          alteracoes: [],
          mantidos: [
            { ticker: 'ITUB4', nome: 'Itaú Unibanco', peso: 60 },
            { ticker: 'TESO', nome: 'Tesouro Selic', peso: 40 },
          ],
        },
      },
      'movimentacoes',
    )
    cy.stubApi('GET', '/relatorios/meus-relatorios*', SEM_RELATORIOS, 'relatorios')

    cy.visit('/')
    cy.wait(['@dashboard', '@performance', '@detalhe'])

    // Carteira vinculada e competência do cliente.
    cy.contains('h1', 'Carteira Moderada').should('be.visible')
    cy.contains('Painel do investidor').should('contain.text', 'Outubro')

    // Indicadores: valores da API, formatados; % do CDI no ano = 12,3 / 10 × 100.
    cy.contains('[data-slot="kpi-card"]', 'Rentabilidade do mês')
      .should('contain.text', '+1,50 %')
      .and('contain.text', 'CDI do mês: +1,00 %')
    cy.contains('[data-slot="kpi-card"]', 'Acumulado no ano')
      .should('contain.text', '+12,30 %')
      .and('contain.text', 'CDI no ano: +10,00 %')
    cy.contains('[data-slot="kpi-card"]', '% do CDI no ano').should('contain.text', '123,0 %')
    cy.contains('[data-slot="kpi-card"]', 'Ativos na carteira')
      .should('contain.text', '2')
      .and('contain.text', 'Carteira Moderada')

    // Sua carteira (cartão do painel) bate com o detalhe.
    cy.contains('Composição · 2 ativos').should('be.visible')
    cy.contains('Itaú Unibanco').should('be.visible')
    cy.contains('Tesouro Selic').should('be.visible')

    // Links abrem os detalhes da MESMA carteira.
    cy.contains('a', 'Ver detalhes').click()
    cy.location('pathname').should('eq', '/carteira')
    cy.contains('h1', 'Carteira Moderada').should('be.visible')
    cy.go('back')
    cy.contains('button', 'Ver carteira completa').click()
    cy.location('pathname').should('eq', '/carteira')
    cy.contains('h1', 'Carteira Moderada').should('be.visible')
    cy.contains('Itaú Unibanco').should('be.visible')
  })
})

export {}
